INSERT INTO clues (dish_id, order_index, text) VALUES
((SELECT id FROM dishes WHERE slug='karaage'), 1, 'Bite-size fried chunks kept hot by the register at a convenience store.'),
((SELECT id FROM dishes WHERE slug='karaage'), 2, 'The frying style dates to the late 1600s; the chicken version spread from Nakatsu and Usa after the war.'),
((SELECT id FROM dishes WHERE slug='karaage'), 3, 'Nakatsu throws a yearly festival for it, with more than 60 shops taking part.'),
((SELECT id FROM dishes WHERE slug='karaage'), 4, 'You marinate thigh pieces in soy sauce, sake, ginger and garlic, dredge them in starch, and deep-fry them.'),
((SELECT id FROM dishes WHERE slug='karaage'), 5, 'Craggy golden nuggets of Japanese fried chicken, served with a lemon wedge and shredded cabbage.'),
((SELECT id FROM dishes WHERE slug='yakisoba'), 1, 'Noodles tossed on a street-stall griddle, loud with scraping spatulas.'),
((SELECT id FROM dishes WHERE slug='yakisoba'), 2, 'Street stalls selling a children''s griddle snack started frying these noodles around 1918.'),
((SELECT id FROM dishes WHERE slug='yakisoba'), 3, 'The name promises buckwheat, but the noodles are wheat, and canteens stuff them into a hot dog bun.'),
((SELECT id FROM dishes WHERE slug='yakisoba'), 4, 'You fry pork and cabbage on a griddle, add steamed wheat noodles, and toss them in thick, fruity brown sauce.'),
((SELECT id FROM dishes WHERE slug='yakisoba'), 5, 'Japan''s griddle noodles, glossy brown under seaweed powder, bonito flakes and pickled ginger.'),
((SELECT id FROM dishes WHERE slug='edamame'), 1, 'Fuzzy green pods next to a cold beer, plus an empty bowl for the shells.'),
((SELECT id FROM dishes WHERE slug='edamame'), 2, 'A monk named Nichiren wrote a thank-you note for a gift of these in 1275.'),
((SELECT id FROM dishes WHERE slug='edamame'), 3, 'You never eat the pod: you squeeze the beans straight into your mouth and toss the husk.'),
((SELECT id FROM dishes WHERE slug='edamame'), 4, 'You boil the pods in well-salted water for a few minutes, then rub coarse salt over them.'),
((SELECT id FROM dishes WHERE slug='edamame'), 5, 'Young soybeans in the pod, a salted Japanese bar snack ordered with the first round.'),
((SELECT id FROM dishes WHERE slug='taiyaki'), 1, 'A street snack people argue about biting head first or tail first.'),
((SELECT id FROM dishes WHERE slug='taiyaki'), 2, 'Seijirō Kobe started selling them in 1909, recasting a round bean cake that wasn''t selling.'),
((SELECT id FROM dishes WHERE slug='taiyaki'), 3, 'The mold copies a sea bream, a pricey lucky fish, so ordinary people could taste one cheaply.'),
((SELECT id FROM dishes WHERE slug='taiyaki'), 4, 'You pour batter into a hinged iron mold, add a spoonful of sweet red bean paste, cover it and flip it over the flame.'),
((SELECT id FROM dishes WHERE slug='taiyaki'), 5, 'A golden fish-shaped waffle from Japan, filled with red bean paste or custard.'),
((SELECT id FROM dishes WHERE slug='tamagoyaki'), 1, 'A neat yellow block, sliced to show a spiral of thin layers.'),
((SELECT id FROM dishes WHERE slug='tamagoyaki'), 2, 'Townspeople ate an early version in the Edo period, and 1950s parents served it for children''s protein.'),
((SELECT id FROM dishes WHERE slug='tamagoyaki'), 3, 'Sushi diners once ordered it first to judge the chef, since it shows skill with no fish to hide behind.'),
((SELECT id FROM dishes WHERE slug='tamagoyaki'), 4, 'You pour thin layers of sweetened beaten egg into a square pan, rolling each one up before adding the next.'),
((SELECT id FROM dishes WHERE slug='tamagoyaki'), 5, 'Japan''s rolled omelette, sweet and dense, served in slices at breakfast and on sushi rice.'),
((SELECT id FROM dishes WHERE slug='galbi'), 1, 'Ribs butterflied into one long flat ribbon still joined to the bone.'),
((SELECT id FROM dishes WHERE slug='galbi'), 2, 'Most credit Korean Americans in Los Angeles with the thin cross-cut style that carries the city''s initials.'),
((SELECT id FROM dishes WHERE slug='galbi'), 3, 'Cooks brush pear juice on before grilling, and leftover marinade turns into a glaze on the fire.'),
((SELECT id FROM dishes WHERE slug='galbi'), 4, 'You soak short ribs in soy sauce, sugar, garlic, scallion and sesame oil, then grill them over charcoal.'),
((SELECT id FROM dishes WHERE slug='galbi'), 5, 'Sweet soy-glazed beef short ribs, wrapped in lettuce with rice at a South Korean barbecue table.'),
((SELECT id FROM dishes WHERE slug='samgyeopsal'), 1, 'Strips you grill yourself at the table and snip apart with scissors.'),
((SELECT id FROM dishes WHERE slug='samgyeopsal'), 2, 'It first turns up in print in a 1984 newspaper, and caught on as pork grew easier to buy in the late 1980s.'),
((SELECT id FROM dishes WHERE slug='samgyeopsal'), 3, 'It gets its own day each spring, March 3, and soju is the standard drink beside it.'),
((SELECT id FROM dishes WHERE slug='samgyeopsal'), 4, 'You grill thick unmarinated slices in their own fat and wrap them in lettuce with garlic and chili paste.'),
((SELECT id FROM dishes WHERE slug='samgyeopsal'), 5, 'South Korea''s grilled pork belly, striped fat and lean, cut into bites and dipped in sesame oil.'),
((SELECT id FROM dishes WHERE slug='bingsu'), 1, 'A heap of icy flakes big enough to share, one spoon per friend.'),
((SELECT id FROM dishes WHERE slug='bingsu'), 2, 'Cooks in the Joseon era served fruit over ice from stone storehouses, and red beans came later.'),
((SELECT id FROM dishes WHERE slug='bingsu'), 3, 'Modern cafés freeze milk instead of water, so the shavings fall like soft snow.'),
((SELECT id FROM dishes WHERE slug='bingsu'), 4, 'You shave a block of frozen milk into a bowl, then pile on sweet red beans, chewy rice cake and condensed milk.'),
((SELECT id FROM dishes WHERE slug='bingsu'), 5, 'Milky shaved ice under red beans, fruit and squares of rice cake, South Korea''s summer dessert.'),
((SELECT id FROM dishes WHERE slug='mandu'), 1, 'Plump half-moons that come pan-fried, steamed or floating in beef broth.'),
((SELECT id FROM dishes WHERE slug='mandu'), 2, 'Mongol rule in the 1300s loosened a Buddhist dislike of meat, and filled dumplings spread through the court.'),
((SELECT id FROM dishes WHERE slug='mandu'), 3, 'A Goryeo-era folk song is set in a shop selling them, run by a foreigner.'),
((SELECT id FROM dishes WHERE slug='mandu'), 4, 'You fold minced pork, tofu, cabbage and glass noodles into thin wrappers and steam or pan-fry them.'),
((SELECT id FROM dishes WHERE slug='mandu'), 5, 'Crisp-bottomed or steamed dumplings from South Korea, dipped in soy sauce and vinegar.'),
((SELECT id FROM dishes WHERE slug='scallion-pancakes'), 1, 'Flaky, chewy wedges you tear apart to see the layers inside.'),
((SELECT id FROM dishes WHERE slug='scallion-pancakes'), 2, 'Street hawkers and restaurant kitchens across China both sell it, and its first cook went unrecorded.'),
((SELECT id FROM dishes WHERE slug='scallion-pancakes'), 3, 'Taiwan''s version gets an egg fried onto one side, with a thinner, wetter dough.'),
((SELECT id FROM dishes WHERE slug='scallion-pancakes'), 4, 'You fold an unleavened dough again and again with oil and chopped scallions between the layers, then pan-fry it.'),
((SELECT id FROM dishes WHERE slug='scallion-pancakes'), 5, 'Crisp at the edges and chewy inside, a Chinese flatbread with a soy and black vinegar dip.'),
((SELECT id FROM dishes WHERE slug='moo-shu-pork'), 1, 'A stir-fry you roll up yourself at the table like a small burrito.'),
((SELECT id FROM dishes WHERE slug='moo-shu-pork'), 2, 'Cooks in Shandong made it first, and it reached restaurants in New York and Washington around 1966.'),
((SELECT id FROM dishes WHERE slug='moo-shu-pork'), 3, 'American kitchens spread hoisin on thin flour pancakes for it, and some have used tortillas.'),
((SELECT id FROM dishes WHERE slug='moo-shu-pork'), 4, 'You stir-fry shredded pork with scrambled egg, wood ear mushrooms and cabbage, then roll it in pancakes with hoisin.'),
((SELECT id FROM dishes WHERE slug='moo-shu-pork'), 5, 'A Chinese stir-fry of pork and egg flecked like osmanthus blossoms, rolled up in thin wrappers.'),
((SELECT id FROM dishes WHERE slug='shumai'), 1, 'Little open-topped cups steaming in a bamboo basket on a rolling cart.'),
((SELECT id FROM dishes WHERE slug='shumai'), 2, 'Food historians place it in Hohhot, filled with mutton, or Guangzhou, with pork and shrimp.'),
((SELECT id FROM dishes WHERE slug='shumai'), 3, 'An orange dot of crab roe or diced carrot sits in the middle, peeking out of the open top.'),
((SELECT id FROM dishes WHERE slug='shumai'), 4, 'You pleat a thin wrapper up around minced pork and shrimp, leave the top open, and steam it.'),
((SELECT id FROM dishes WHERE slug='shumai'), 5, 'One of the four standards of dim sum in China, a pleated pork and shrimp cup with an orange top.'),
((SELECT id FROM dishes WHERE slug='mooncake'), 1, 'Heavy pastries in fancy gift tins, handed out to clients each autumn.'),
((SELECT id FROM dishes WHERE slug='mooncake'), 2, 'A folk tale says rebels hid messages inside them to coordinate a rising against the Yuan dynasty.'),
((SELECT id FROM dishes WHERE slug='mooncake'), 3, 'A salted duck egg yolk sits in the centre, so a cut slice shows a gold circle.'),
((SELECT id FROM dishes WHERE slug='mooncake'), 4, 'You wrap sweet lotus seed paste around a salted yolk, press it into a carved wooden mold, and bake it.'),
((SELECT id FROM dishes WHERE slug='mooncake'), 5, 'China''s Mid-Autumn Festival pastry, stamped with characters and shared under the full moon.'),
((SELECT id FROM dishes WHERE slug='mongolian-beef'), 1, 'A sticky, sweet stir-fry served over crunchy fried noodles.'),
((SELECT id FROM dishes WHERE slug='mongolian-beef'), 2, 'A Beijing-born comedian opened grill restaurants in Taipei in the 1950s, and the dish grew out of that wave.'),
((SELECT id FROM dishes WHERE slug='mongolian-beef'), 3, 'Despite what the menu says, it has no link to the steppe nation it is named for.'),
((SELECT id FROM dishes WHERE slug='mongolian-beef'), 4, 'You sear thin flank steak, then toss it with scallions in soy sauce, brown sugar, garlic and ginger.'),
((SELECT id FROM dishes WHERE slug='mongolian-beef'), 5, 'Glossy beef and scallion strips, invented in Taiwan and adopted by American Chinese takeout.'),
((SELECT id FROM dishes WHERE slug='fortune-cookie'), 1, 'Handed out with the check at a Chinese restaurant, wrapped in cellophane.'),
((SELECT id FROM dishes WHERE slug='fortune-cookie'), 2, 'A San Francisco tea garden and two Los Angeles businessmen all claim the first one.'),
((SELECT id FROM dishes WHERE slug='fortune-cookie'), 3, 'A 1983 mock trial in San Francisco ruled for the tea garden, and Los Angeles refused the verdict.'),
((SELECT id FROM dishes WHERE slug='fortune-cookie'), 4, 'You bake thin circles of sweet wafer batter, then fold each one around a paper slip before it cools and sets.'),
((SELECT id FROM dishes WHERE slug='fortune-cookie'), 5, 'A crisp folded wafer with a paper prophecy inside, Japanese American in origin and rare in China.'),
((SELECT id FROM dishes WHERE slug='beef-noodle-soup'), 1, 'A dark red broth some vendors simmer for more than a day.'),
((SELECT id FROM dishes WHERE slug='beef-noodle-soup'), 2, 'Sichuan-born veterans who crossed with the Nationalists after 1949 created the red-braised version.'),
((SELECT id FROM dishes WHERE slug='beef-noodle-soup'), 3, 'Menus on the island still call it Sichuan-style, after the men who made it, not the place it was made.'),
((SELECT id FROM dishes WHERE slug='beef-noodle-soup'), 4, 'You braise shank in soy sauce, chili bean paste and star anise until tender, then ladle it over thick wheat strands.'),
((SELECT id FROM dishes WHERE slug='beef-noodle-soup'), 5, 'Taiwan''s bowl of braised beef chunks in spicy broth, with pickled mustard greens on top.'),
((SELECT id FROM dishes WHERE slug='popcorn-chicken'), 1, 'Hot bites shaken in a paper bag at a night market stall.'),
((SELECT id FROM dishes WHERE slug='popcorn-chicken'), 2, 'An American fried chicken chain launched its own version in 1992, inspired by street stalls on the island.'),
((SELECT id FROM dishes WHERE slug='popcorn-chicken'), 3, 'A handful of basil leaves goes into the fryer at the end and comes out glassy and crisp.'),
((SELECT id FROM dishes WHERE slug='popcorn-chicken'), 4, 'You marinate chicken chunks in soy, garlic and five-spice, then coat them in sweet potato starch for the fryer.'),
((SELECT id FROM dishes WHERE slug='popcorn-chicken'), 5, 'Taiwan''s night-market fried chicken, salty and peppery, tossed with crisp basil leaves.'),
((SELECT id FROM dishes WHERE slug='bubble-waffle'), 1, 'Golden spheres joined in a sheet, snapped off one by one as you walk.'),
((SELECT id FROM dishes WHERE slug='bubble-waffle'), 2, 'One theory says postwar hawkers used an egg-shaped mold because real eggs were too costly for the batter.'),
((SELECT id FROM dishes WHERE slug='bubble-waffle'), 3, 'Shops now curl it into a cone and stuff it with ice cream and fruit.'),
((SELECT id FROM dishes WHERE slug='bubble-waffle'), 4, 'You pour sweet egg batter into a hinged pan of round cells and cook it over the flame until the pockets puff.'),
((SELECT id FROM dishes WHERE slug='bubble-waffle'), 5, 'Hong Kong''s ''little eggs'', a crisp sheet of sweet puffs sold hot on the street.');
